 map<int,int> mp;
 int ans;
 void deal( int v ){
 	if ( mp[v] <= 1 ) return;
 	mp[v-1] ++;
 	mp[v+1] ++;
 	mp[v]--;mp[v]--;
 	ans++;
 	deal(v-1);
 	deal(v+1);
 	deal(v);
 }
