 const int MAX = 1007;

 map<PII,int> M;

 vector<PII> G[MAX];

 bool U[MAX];

 bool ok = 1;

 void dfs(int v, int p, int dir)
 {
 	U[v] = 1;
 	int bal = 0;
 	FOR(i,0,SZ(G[v]))
 	{
 		int to = G[v][i].first;
 		if (to == p && G[v][i].second == dir) continue;
 		if (!U[to])
 			dfs(to, v , -G[v][i].second);
 		PII e;
 		if (G[v][i].second == 1)
 			e = MP(v , to);
 		else
 			e = MP(to, v);
 		if (!M.count(e))
 		{
 			M[e] = G[v][i].second;
 		}
 		bal += M[e] * G[v][i].second;
 	}
 	if (p != -1)
 	{
 		if (bal == 0)
 		{
 			ok = 0;
 		}
 		PII e;
 		if (dir == 1)
 			e = MP(v , p);
 		else
 			e = MP(p , v);
 		M[e] = - bal * dir;
 	}
 }

