 const int N = 2008;

 typedef struct Tour {
 	int to, hour, duration;
 	bool used;
 } Tour;
 int totalUsed;
 vector<Tour> graph[N];

 int n;

 bool vis[N];

 bool reachDFS(int v, int target) {
 	if (v == target) return true;
 	if (vis[v]) return false;
 	vis[v] = true;
 	for (Tour & t : graph[v]) {
 		if (!t.used) {
 			if (reachDFS(t.to, target)) {
 				return true;
 			}
 		}
 	}
 	return false;
 }

 bool reachablePast(int v, Tour & t) {
 	fori (i, 1, n + 1) vis[i] = false;
 	assert(!t.used);
 	t.used = true;
 	bool ret = reachDFS(t.to, v);
 	t.used = false;
 	return ret;
 }

 int endTime(Tour & t, int now) {
 	if (now % 24 <= t.hour) {
 		return now + (t.hour - now % 24);
 	} else {
 		return now + 24 + (t.hour - now % 24);
 	}
 }

 int dfs(int v, int now) {
 	if (totalUsed == n * 2) return now;
 	int best = OO;
 	// If at least one is used, or we're 1 because idk, then just go
 	if (v == 1 || graph[v][0].used || graph[v][1].used) {
 		for (Tour & t : graph[v]) {
 			if (t.used) continue;
 			int nxt = endTime(t, now);
 			assert(!t.used); t.used = true; totalUsed++;
 			minify(best, dfs(t.to, nxt + t.duration));
 			t.used = false; totalUsed--;
 		}
 	} else {
 		assert(!graph[v][0].used && !graph[v][1].used);
 		if (!reachablePast(v, graph[v][0])) {
 			Tour & t = graph[v][1];
 				int nxt = endTime(t, now);
 				assert(!t.used); t.used = true; totalUsed++;
 				minify(best, dfs(t.to, nxt + t.duration));
 				t.used = false; totalUsed--;
 		} else if (!reachablePast(v, graph[v][1])) {
 			Tour & t = graph[v][0];
 				int nxt = endTime(t, now);
 				assert(!t.used); t.used = true; totalUsed++;
 				minify(best, dfs(t.to, nxt + t.duration));
 				t.used = false; totalUsed--;
 		} else {
 			// both are reachable, greedy.
 			Tour & t = graph[v][endTime(graph[v][1], now) < endTime(graph[v][0], now)];
 				int nxt = endTime(t, now);
 				assert(!t.used); t.used = true; totalUsed++;
 				minify(best, dfs(t.to, nxt + t.duration));
 				t.used = false; totalUsed--;
 		}
 	}
 	return best;
 }

 void tc(int tci) {
 	scan_d(n);
 	fori (i, 1, n + 1) {
 		graph[i].clear();
 		repeat(2) {
 			int to, hour, duration;
 			scan_ddd(to, hour, duration);
 			graph[i].push_back((Tour) {
 				.to = to,
 				.hour = hour,
 				.duration = duration,
 				.used = false
 			});
 		}
 	}
 	totalUsed = 0;
 	printf("Case #%d: %d\n", tci, dfs(1, 0));
 }

 int main() {
 	int tcn;
 	scanf("%d", &tcn);
 	fori (i, 0, tcn) tc(i+1);
 }

#include"stdio.h"
 #include"set"
 using namespace std;
 struct dist
 {
   int d;
   int index;
   set<int> surround;
   bool operator<(const dist di)const
   {
     if(d!=di.d)return d<di.d;
     if(surround.size()!=di.surround.size())return (surround.size()<di.surround.size());
     return index<di.index;
   }
 };
 int main()
 {
   int T;
   scanf("%d",&T);
   for(int t=1;t<=T;t++)
   {
     int n,m;
     scanf("%d%d",&n,&m);
     set<int> graph[n];
     while(m--)
     {
       int a,b;
       scanf("%d,%d",&a,&b);
       graph[a].insert(b);
       graph[b].insert(a);
     }
     dist d[n];
     set<dist> next;
     for(int x=1;x<n;x++){d[x].d=n+1;d[x].index=x;next.insert(d[x]);}
     d[0].d=0;
     d[0].index=0;
     next.insert(d[0]);
     while(next.begin()->index!=1)
     {
       int u=next.begin()->index;
       next.erase(next.begin());
       for(set<int>::iterator it=graph[u].begin();it!=graph[u].end();it++)
       {
 	dist d1;
 	d1.index=*it;
 	d1.d=d[u].d+1;
 	d1.surround=d[u].surround;
 	d1.surround.insert(graph[u].begin(),graph[u].end());
 	if(d1<d[*it])
 	{
 	  if(next.count(d[*it])!=1)printf("OOPS %d",*it);fflush(stdout);
 	  next.erase(next.find(d[*it]));
 	  d[*it]=d1;
 	  next.insert(d[*it]);
 	}
       }
     }
     int r=d[1].surround.size()-d[1].d;
     if(d[1].d==1)r++;
     printf("Case #%d: %d %d\n",t,d[1].d-1,r);
   }
 }

