 	int x, y, k;

 	square() {
 		x = 0; y = 0; k = 0;
 	}

 	square(int i, int j, int q) {
 		x = i; y = j; k = q;
 	}

 	friend bool operator < (square a, square b) {
 		bool f = false;
 		if (a.k < b.k) f = true;
 		if (a.k == b.k && a.x > b.x) f = true;
 		if (a.k == b.k && a.x == b.x && a.y > b.y) f = true;
 		return f;
 	}
 };


