 using namespace std;
 int dp[600][600];
 int M=100003;

 bool poss(int pos,int i,int mark)
 {
 	if(mark-pos<pos-i)
 		return 0;
 	return 1;
 }

 int permut(int D)
 {
 	int res=1;
 	for(int i=1;i<=D;++i)
 	{
 		res*=i;
 		res%=M;
 	}
 	return res;
 }

 int cal(int pos,int i,int mark)
 {
 	int N=mark-pos-1;
 	int D=pos-i-1;
 	if(N==0) return 0;
 	if(N==1 && D==1) return 0;
 	int D1=N-D;
 	int x=permut(N)/(permut(D)*permut(D1));
 	if(x>0)
 	return x-1;
 }


 int solve(int mark,int pos)
 {
 	if(pos==1)
 		return 1;
 	int &res=dp[mark][pos];
 	res=0;
 	for(int i=1;i<mark;++i)
 	{
 		if(poss(pos,i,mark))
 		{
 			res+=solve(pos,i)+cal(pos,i,mark);

 			res%=M;
 		}

 	}
 //	cout<<mark<<" "<<pos<<" "<<res<<"\n";
 	return res;
 }


 int main()
 {
 	int T,n;
 	cin>>T;
 	for(int i1=1;i1<=T;++i1)
 	{
 		cin>>n;
 		int res=0;
 		for(int i=1;i<n;++i)
 		{
 			res+=solve(n,i);
 			res%=M;
 		}
 		cout<<"Case #"<<i1<<": "<<res<<"\n";
 	}


 }
