 void init() {}



 BEGIN_SOLVER ///////////////////////////////////////////////////////////////////////////////////////

 ll H, W, N[2], V[2], Y, X, VY, VX;
 ll P[2][1000010];


 void input() {
   cin >> H >> W;
   cin >> N[0] >> N[1];
   cin >> V[0] >> V[1];
   cin >> Y >> X >> VY >> VX;
 }

 inline ll mod(ll a, ll m) { return (a % m + m) % m; }

 void move(ll t) {
   Y = mod(Y + t * VY, 2 * H);
   if (Y >= H) {
     Y = 2 * H - Y;
     VY *= -1;
   }
 }

 void solve() {
   H *= llabs(VX);
   Y *= llabs(VX);
   VX /= llabs(VX);

   if (ld(V[0]) * (W * 2) * N[0] >= H &&
       ld(V[1]) * (W * 2) * N[1] >= H) {
     puts("DRAW");
     return;
   }

   if (VX > 0) { move(W - X); X = W; }
   else        { move(X);     X = 0; }

   ll T[2] = {0, 0};
   memset(P, -1, sizeof(P));
   rep (iter, 1000000000) {
     int s = (X == 0 ? 0 : 1);
     int k = T[s] % N[s];

     if (P[s][k] != -1) {
       ll t = N[s] * W * 2;
       ll dy = llabs(P[s][k] - Y);
       if (dy > t * V[s]) {
         // Lose!
         printf("%s %lld\n", s == 0 ? "RIGHT" : "LEFT", T[s]);
         return;
       }
     }
     P[s][k] = Y;
     ++T[s];

     move(W);
     X = W - X;
   }

   puts("DRAW");
 }










