 int count( int x, int y )
 {
 	if( x < 0 || y < 0 ) return 0;
 	if( ( x + y ) % 3 ) return 0;
 	if( x > y ) swap( x, y );
 	int a = y - x;
 	x -= a;
 	if( x < 0 ) return 0;
 	int b = ( x ) / 3;
 	return cnk( b, a + b + b );
 }

