 		{
 			int cur = 1;
 			int mask = 1 + ( i << 1 ) + ( 1 << ( 1 + n ) );
 			vector< int > q;
 			fj( 2 + n ) if( mask & ( 1 << j ) ) q.pb( j );
 			fj( q.size( ) - 1 ) ( cur *= num[q[j]][q[j + 1]] ) %= mod;
 			if( cnt[i] % 2 == 0 ) ans += cur;
 			else ans -= cur;
 			ans = ( ans + mod ) % mod;
 		}
 		printf( "Case #%d: %d\n", tt, ans );
 	}

 	return 0;
 }

