 int solve(int n)
 {
 	for (int i = 0; i < n; ++i)
 		scanf("%lld", &a[i]);		
 	ll mx = a[0]; ll mn = a[0];
 	for (int i = 1; i < n; ++i) {
 		if (a[i] > mx) mx = a[i];
 		if (a[i] < mn) mn = a[i];
 	}

 	 nod = abs(mx - mn);
 	for (int i = 0; i < n; ++i)
 		for (int j = i+1; j < n; ++j)
 			if (nod > 0 && a[i] != a[j])
 				nod = gcd(nod, abs(a[i] - a[j]));
 	if (a[0] % nod == 0) return 0;
 	return nod - a[0] % nod;
 }


