 int main()
 {
    freopen("input.txt" ,"rt", stdin); freopen("output.txt", "wt", stdout);

    int i, j, k;
    primes[0] = 0;
    for (i = 2; i < maxn; i++) {
       if (!seq[i]) {
          seq[i] = 2;
          primes[++primes[0]] = i;
          j = i+i;
          while (j < maxn) {
             seq[j] = 1;
             j += i;
          }
       }
