                }
             }
             if (ans.size() > 1) break;
          }
          if (ans.size() != 1) cout << "I don't know.";
          else cout << *(ans.begin());
       } else cout << "I don't know.";

       cout << endl;
    }


    fclose(stdin); fclose(stdout);
    return 0;   
 }
#include <iostream>

 using namespace std;



 int r, c;
 int a[10][10];

 void Load()
 {
 	cin >> r >> c;
 	for (int i = 0; i < r; i++)
 		for (int j = 0; j < c; j++)
 		{
 			cin >> a[i][j];
 		}
 }


 int b[10][10];

 const int dx[9] = {-1,-1,-1,0,0,0,1,1,1};
 const int dy[9] = {-1,0,1,-1,0,1,-1,0,1};

 void Solve()
 {
 	int ans = 0;
 	int m;
 	int mm = (1 << (r*c));
 	int i, j, k, f, isg;
 	for (m = 0; m < mm; m++)
 	{
 		k = 0;
 		for (i = 1; i <= r; i++)
 		{
 			for (j = 1; j <= c; j++)
 			{
 				if ((m & (1 << k)) > 0)
 					b[i][j] = 1;
 				else
 					b[i][j] = 0;
 				k++;
 			}

 		}

 		isg = 1;
 		for (i = 1; i <= r; i++)
 			for (j = 1; j <= c; j++)
 			{
 				k = 0;
 				for (f = 0; f < 9; f++)
 					k += b[i+dx[f]][j+dy[f]];
 				if (k != a[i-1][j-1])
 					isg = 0;
 			}
 	   if (isg)
 	   {
 		   	k = 0;
 	   		for (i = 1; i <= c; i++)
 	   		{
 	   			k += b[(r+1)/2][i];
 	   		}
 	   		if (k > ans) ans = k;
 	   }
 	}
 	cout << ans << "\n";
 }


 int main()
 {
 	freopen("input.txt", "rt", stdin);
 	freopen("output.txt", "wt", stdout);
 	int nt, tt;
 	cin >> nt;
 	for (tt = 1; tt <= nt; tt++)
 	{
 		Load();
 		cout << "Case #" << tt << ": ";
 		Solve();
 	}
 	return 0;
 }

