 ll F;

 void input() {
   cin >> N;
   rep (i, N) cin >> X[i];
   cin >> F;
 }


 void solve() {
   sort(X, X + N);
   ll leftx = X[0];
   ll rightx = X[N - 1];
   N = remove(X, X + N, leftx) - X;
   N = remove(X, X + N, rightx) - X;
   N = remove(X, X + N, 0) - X;

   F -= (rightx - leftx) * 2;
   if (F < 0) {
     puts("NO SOLUTION");
     return;
   }

   // rep (i, N) printf("%lld ", X[i]); puts("");

   int L = N / 2, R = N - L;

   vector<ll> LS[20][2];
   vector<ll> RS[20][2];

   int bub = (int)round(pow(3.0, L));
   for (int b = 0; b < bub; ++b) {
     int t = b;

     int le = 0;
     ll d = 0;
     rep (i, L) {
       int k = t % 3;
       t /= 3;
       if (k == 1) {
         ++le;
         d -= X[i] * 2;
       }
       else if (k == 2) {
         if (le == 0) goto ng;
         --le;
         d += X[i] * 2;
       }
     }

     LS[le][0].pb(d);


     t = b;
     rep (i, L) {
       int k = t % 3;
       t /= 3;
       if (k == 0) LS[le][1].pb(d + 2 * llabs(X[i]));
     }

   ng:;
   }


   bub = (int)round(pow(3.0, R));
   for (int b = 0; b < bub; ++b) {
     int t = b;
     int ri = 0;
     ll d = 0;
     rep (i, R) {
       ll x = X[N - i - 1];
       int k = t % 3;
       t /= 3;

       if (k == 1) {
         if (ri == 0) goto ng2;
         --ri;
         d -= x * 2;
       }
       else if (k == 2) {
         ++ri;
         d += x * 2;
       }
     }

     RS[ri][0].pb(d);


     t = b;
     rep (i, R) {
       ll x = X[N - i - 1];
       int k = t % 3;
       t /= 3;

       if (k == 0) RS[ri][1].pb(d + 2 * llabs(x));
     }
   ng2:;
   }

   ll ans = 0;

   // puts("");

   for (int i = 0; i <= min(L, R); ++i) {
     for (int a = 0; a <= 1; ++a) {
       for (int b = 0; b <= 1; ++b) {
         if (a == 1 && b == 1) continue;

         vector<ll> &ls = LS[i][a];
         vector<ll> &rs = RS[i][b];

         sort(all(ls));
 sort(all(rs));
     reverse(all(rs));

     /*
     printf("i=%d\n", i);
     // printf(" %d %d\n", ls.size(), rs.size());
     rep (i, ls.size()) printf(" %lld", ls[i]); puts("");
     rep (i, rs.size()) printf(" %lld", rs[i]); puts("");
     */

     int j = 0;
     rep (i, ls.size()) {
       while (j < (int)rs.size() && rs[j] + ls[i] > F) {
         ++j;
       }

       if (j < (int)rs.size()) {
         ans = max(ans, rs[j] + ls[i]);
       }
     }
       }
     }
   }

   printf("%lld\n", ans + (rightx - leftx) * 2);
 }











