     int res=666;
     REP(x, N) if (vi[x] == -1) {
         int cur=0;
         REP(z, N) if (!used[z]) {
             vector<int> next = vi;
             next[x] = z;
             int c=cost(next);
             if (c >= 666) continue;
             cur = max(cur, 1+c);
         }
         res = min(res, cur);
     }

     //printvi(vi);
     //cout<<"  ==>"<<res<<endl;

     return memo[N][vi] = res;
 }

 void solve() {
     cin>>N;
     card = V(N);
     REP(i, N) { cin>>card[i]; card[i]--; } // 0-indexed

     V perm(N, 0);
     REP(i, N) perm[i] = i;

     arr.clear();
     do {
             // check
         bool valid=true;
         REP(i, N) FOR(j, i+1, N) FOR(k, j+1, N) {
             if (perm[i] > perm[j] && perm[j] > perm[k]) valid = false;
         }
         if (valid) arr.push_back(perm);

     } while (next_permutation(perm.begin(), perm.end()));

     // cout<<SZ(arr)<<endl;

     // memo.clear();

         // find the best adversary
     V res(N, -666);
     FORIT(it, arr) {
         V adv = *it; // adversary

             // determine this is an enough adversary or not
         V state(N, -1);
         bool valid = true;

         REP(i, N) {
             if (cost(state) != N-i) { valid=false; break; }
             state[card[i]] = adv[card[i]];
         }

         if (valid) res = max(res, adv);
     }

     REP(i, N) printf(" %d", res[i]+1); // 1-indexed
     puts("");
 }

 int main() {
     int total; cin>>total;
     for (int test=1; test<=total; test++) {
         printf("Case #%d:", test);
         solve();
     }
 }

