 double min_p(double rest, int e)
 {
 	rest *= x;

 	vector<double> a;
 	for (int i = 0; i < n; ++i)
 		if (i != e)
 			a.push_back(s[i]);
 	a.push_back(1e30);
 	sort(all(a));
 	for (int i = 0; i < a.size(); ++i)
 	{
 		if (a[i] + EPS < a[i + 1])
 		{
 			int num = i + 1;
 			double use = min(rest, num * (a[i + 1] - a[i]));
 			rest -= use;
 			a[i] += use / num;
 			if (rest < EPS)
 				return a[i];
 		}
 	}

 	return 1e50;
 }
