 long long gcd(long long a,long long b)
 {
   if(b == 0)
     return a;
   else
     return gcd(b,a%b);
 }
 int win(long long x,long long y)
 {
   long long val = gcd(x,y);
   if(x == y)
     return -1;
   else if(y%x == 0 || x%y == 0)
     return 1;
   else if(val == x-y || val == y-x)
     {
       return -1;
     }
   else if(x>y && x<2*y || y>x &&y<2*x)
     {
       if(y>x)
 	return -win(x,y-x);
       else
 	return -win(x-y,y);
