 #define maxn 107
 #define zero 1e-9

 class point
 {
 public:
     double x, y;
     point():x(0),y(0){};
 };

 int cases;
 point l[maxn], r[maxn];
 int n, m;
 int n1, n2;
 double a, at;
 int now;

 double operator*(point p, point q)
 {
     return(p.x*q.y-p.y*q.x);
 }
 double make(point p, point q, double mid)
 {
     double w(0);
     if (q.x-p.x < zero) return q.y;
     w = double((q.y-p.y)/(q.x-p.x));
     w *= mid-p.x;
     return w+p.y;
 }
 bool check(double mid)
 {
     int i;
     double w(0);
     double y1, y2;
     point p1, p2;
     w = r[1]*l[1];
     for (i = 2; i <= n1; ++i) if (l[i].x < mid) {
       w += l[i-1]*l[i];
     }
     else break;
     y1 = make(l[i-1],l[i],mid);
     p1.x = mid; p1.y = y1;
     w += l[i-1]*p1;
     for (i = 2; i <= n1; ++i) if (r[i].x < mid) {
       w += r[i]*r[i-1];
     }
     else break;
     y2 = make(r[i-1],r[i],mid);
     p2.x = mid; p2.y = y2;
     w += p2*r[i-1];
     w += p1*p2;

     return (w-a >= -zero);
 }
 double calc()
 {
     double ll, rl, mid;
     ll = 0; rl = n;
     while (rl-ll > 0.0000001) {
       mid = (rl+ll)/2.0;
       if (check(mid)) rl = mid;
       else ll = mid;
     }
     if (check(ll)) return ll;
     return rl;
 }
