       at = 0; 
       for (int i = 1; i <= n1; ++i){
         scanf("%lf%lf",&l[i].x,&l[i].y);
         if (i > 1) 
           at += l[i-1]*l[i];
       }
       for (int i = 1; i <= n2; ++i){
         scanf("%lf%lf",&r[i].x,&r[i].y);
         if (i > 1) 
           at += r[i]*r[i-1];
       }
       at += l[n1]*r[n2]+r[1]*l[1];
       at /= m;
       a = 0;
       for (int i = 1; i < m; ++i) {
         a += at;
         printf("%.6lf\n",calc());
       }

     }
     return 0;
 }

