 	for(ll v = cnt1; v > 1; ){
 		if (cur_hd <= cur_ak){
 			ans++;
 			cur_hd = hd - cur_ak;
 			if (cur_hd <= cur_ak){
 				return INF;
 			}
 		} else {
 			v--;
 			ans++;
 			cur_hd -= cur_ak;
 		}
 	}

 	ans++;
 	return ans;
 }


 void solve(int t){
 	scanf("%lld%lld%lld%lld%lld%lld", &hd, &ad, &hk, &ak, &b, &d);
 	cnt1 = 0;
 	if (ad >= hk){
 		cnt1 = 1;
 	} else if (b == 0){
 		cnt1 = (hk + ad - 1) / ad;
 	} else {
 		cnt1 = INF;
 		ll x, y;
 		for(y = 0; y < 1e5; y++){
 			ll v = ad + y * b;
 			x = (hk + v - 1) / v;
 			cnt1 = min(cnt1, x + y);
 		}
 	}

 	printf("Case #%d: ", t);


 	ll cnt2 = (hd + ak - 1) / ak;

 	//printf("%lld %lld ", cnt1, cnt2);

 	if (cnt1 <= cnt2){
 		printf("%lld\n", cnt1);
 		return;
 	}

 	/*if (max(0ll, ak - d) * 2 >= hd){
 		printf("IMPOSSIBLE\n");
 		return;
 	}*/

 	ll ans = INF;
 	ll d_lim = 0;
 	if (d > 0){
 		d_lim = (ak + d - 1) / d;
 	}

 	for(ll y = 0; y <= min((ll)1e6, d_lim); y++){
 		ans = min(ans, solve_d(y));
 	}
 	for(ll y = max(0ll, d_lim - (ll)1e6); y <= d_lim; y++){
 		ans = min(ans, solve_d(y));
 	}

 	if (ans == INF){
 		printf("IMPOSSIBLE\n");
 		return;
 	}

 	printf("%lld\n", ans);
 }   

