 using namespace std;


 bool can_do_it(int ratio, int req, int quantity){


     if(ratio == 0) return false;

     if((100*quantity>=90*req) && (100*quantity <= 110*req)){
         return true;
     }

     return false;
 }

 int solve(vector<int>& R, vector<vector<int> >&Q){

     int N = R.size();
     int P = Q[0].size();

     vector<vector<int> > sorted_Q(N);

     for(int i=0; i<N; i++){

         sort(Q[i].begin(), Q[i].end());
         sorted_Q[i] = Q[i];
     }

     vector<int> index(N, 0);

     bool is_completed = false;

     int num_packages = 0;

     while(true){

         for(int i=0; i<N; i++){

             if(index[i]>= P) {
                 is_completed = true;
                 break;
             }
         }

         if(is_completed) break;


         vector<int> row(N);

         for(int i=0; i<N; i++){

             row[i] = sorted_Q[i][index[i]];
         }

         int min_quantity = *min_element(row.begin(), row.end());
         int min_idx;

         for(int i=0; i<N; i++){

             if(row[i] <= min_quantity){
                 min_idx = i;
                 break;
             }
         }
         vector<vector<int> > servings(N);

         for(int i=0; i<N; i++){

             int ratio = row[i]/R[i];

             for(int j=0; j<10; j++){

                 if(can_do_it(ratio+j, R[i], row[i])) servings[i].push_back(ratio+j);

             }


         }


         bool found = false;
         for(int s:servings[min_idx]){

             int num_found = 0;

             for(int i=0; i<N; i++){

                 if(find(servings[i].begin(), servings[i].end(), s) != servings[i].end()){

                     num_found++;
                 } else {
                     break;
                 }
             }

             if(num_found == N){

                 found = true;

                 num_packages++;

                 for(int i=0; i<N; i++) index[i]++;

                 break;
             }
         }

         if(!found){

             index[min_idx]++;
         }

     }



     return num_packages;
 }

