     for(int c=1; c<=T; c++){

         int N, P;
         cin>>N>>P;

         vector<int> R(N);
         for(int i=0; i<N; i++) cin>>R[i];

         vector<vector<int> > Q(N, vector<int>(P, 0));

         for(int i=0; i<N; i++){

             for(int j=0; j<P; j++){
                 cin>>Q[i][j];
             }
         }

         cout<<"Case #"<<c<<": "<<solve(R, Q)<<endl;

     }

     return 0;
 }

