     if(x>=temp.size()){
         if(any_of(pre.begin(),pre.end(),[](int x){return x!=0;}))return;
         dfs(temp);
         return;
     }
     temp[x]='0';
     gennext(pre,temp,x+1);
     for(int i = 0 ; i < temp.size() ; i ++){
