 double distance(double p1x,double p1y,double p2x,double p2y){
 	return abs(p1x-p2x)+abs(p1y-p2y); //(p1x-p2x)*(p1x-p2x)+(p1y-p2y)*(p1y-p2y);
 }

 double distancesq(double p1x,double p1y,double p2x,double p2y){
 	return (p1x-p2x)*(p1x-p2x)+(p1y-p2y)*(p1y-p2y);
 }


 struct point{
 	int x,y;
 	double dist;

 	point(int _y,int _x,double _dist){
 		x=_x;
 		y=_y;
 		dist=_dist;
 	}

 	bool operator<(const point &other) const{
 		if(dist!=other.dist)
 			return dist<other.dist;
 		else{
 			//cout<<"called for "<<x<<","<<y<<" vs "<<other.x<<","<<other.y<<endl;
 			return distancesq(clickX,clickY,x,y)<distancesq(clickX,clickY,other.x,other.y);
 		}
 	}

 };

 bool goodPos(int y,int x){
 	return !((y==clickY && x==clickX) || (y==clickY-1 && x==clickX) || (y==clickY && x==clickX+1) || (y==clickY-1 && x==clickX+1) );
 }


