 using namespace std;
 int P[1001];
 int B[1001];
 multiset<int> CS[1001];
 bool used[1001];
 pair<int, int> solveCase(int N,int C, int M) {
     int rides = 0 ;
     int proms = 0;
     multiset<pair<int, int> > Q;
     for(int i=0;i<M;i++) {
         Q.insert({P[i],B[i]});
     }

     while(!Q.empty()) {
        ++rides;
         memset(used,false,1001*sizeof(bool));
         int currentSeat = 1;
         std::vector<pair<int, int> > toErase;

         for(auto tkt:Q) {
             if(used[tkt.second])
                 continue;
             if(tkt.first >=currentSeat) {
                 currentSeat++;
                 toErase.push_back({tkt.first, tkt.second});
                 used[tkt.second] = true;
             }
         }



         for(auto c:toErase) {
             Q.erase(Q.find(c));
         }
     }

     for(int i=0;i<=C;i++) {
         CS[i].clear();
     }

     for(int i=0;i<M;i++) {
         CS[P[i]].insert(B[i]);
     }

     for(int i=1;i<=C;i++) {
        // cout << "BLA" << CS[i].size()<< " "<< rides << endl;
         if(CS[i].size() > rides) {
             proms += CS[i].size() - rides;
         }

     }

     return {rides,proms};

 }


 int main() {
     int testCases;
     cin >> testCases;
     for(int i=0;i<testCases; i++) {
         int N,C,M;
         cin>> N>>C>>M;
         for(int i=0;i<M;i++) {
             cin >> P[i] >> B[i];
         }
         auto c= solveCase(N,C,M);
         cout << "Case #" << (i + 1) << ": " << c.first <<" "<< c.second << endl;

     }

 }
