 bool containsE(int s, int e, int a, int b) {
   int nd = ds[s][e];
   assert(nd < inf);
   if (nd == ds[s][a] + 1 + ds[b][e]) return true;
   if (nd == ds[s][b] + 1 + ds[a][e]) return true;
   return false;
 }
 bool containsV(int s, int e, int v) {
   if (v == e) return false;
   return ds[s][e] == ds[s][v] + ds[v][e];
 }

