 void solve() {
 	pp[1] = 0;
 	pp[2] = 1;
 	pps[2] = 1;

 	for (int i = 3; i <= n; i++) {
 		pp[i] = (r[i-1] + pps[i-2] * r[i-1]) % m;
 		pps[i] = (pps[i-1] + pp[i]) % m;
 	}

 	int l = k;
