 			{
 				res++;
 				was.pb(mp(fx, fy));
 			}
 		}

 		for (int y = -1; ; y--)
 		{
 			int fy = ((abs(y) & 1) ? h * (y + 1) - sy : h * y + sy);

 			if (dist2(sx, sy, fx, fy) > d * d) break;

 			if (check(fx, fy))
 			{
 				res++;
 				was.pb(mp(fx, fy));
 			}
 		}
 	}

 	for (int x = -1; ; x--)
 	{
 		int fx = ((abs(x) & 1) ? w * (x + 1) - sx : w * x + sx);
 		if (abs(fx - sx) > d) break;

 		for (int y = 0; ; y++)
 		{
 			if (x == 0 && y == 0) continue;
 			int fy = ((y & 1) ? h * (y + 1) - sy : h * y + sy);

 			if (dist2(sx, sy, fx, fy) > d * d) break;

 			if (check(fx, fy))
 			{
 				res++;
 				was.pb(mp(fx, fy));
 			}
 		}

 		for (int y = -1; ; y--)
 		{
 			int fy = ((abs(y) & 1) ? h * (y + 1) - sy : h * y + sy);

 			if (dist2(sx, sy, fx, fy) > d * d) break;

 			if (check(fx, fy))
 			{
 				res++;
 				was.pb(mp(fx, fy));
 			}
 		}
 	}

 	return res;
 }

