 class DisjointSet
 {
 	private:
 		int nSets;
 		VI prev;

 	public:
 		DisjointSet(int N) : prev(N) {
 			REP(i, N)
 				prev[i] = i;
 			nSets = N;
 		}

 		int findRoot(int v) {
 			if (prev[v] == v)
 				return v;
 			return prev[v] = findRoot( prev[v] );
 		}

 		void unite(int u, int v) {
 			u = findRoot(u);
 			v = findRoot(v);
 			if (u != v) {
 				nSets--;
 				prev[u] = v;
 			}
 		}

 		int getNumSets() { return nSets; }
 };

 VI primes;

 bool isPrime(int P) {
 	REP(i, primes.sz) {
 		int p = primes[i];
 		if (p*p > P)
 			break;
 		if (P % p == 0)
 			return false;
 	}
 	return true;
 }

 i64 solve()
 {
 	i64 A, B, P;
 	cin >> A >> B >> P;
 	int nums = B-A+1;

 	DisjointSet ds(nums);
 	while (P <= nums) {
 		if (isPrime(P)) {
 			i64 first = (A+P-1)/P, last = B/P;
 			first *= P;
 			last *= P;
 			while (first < last) {
 				ds.unite(first-A, last-A);
 				first += P;
 			}
 		}
 		P++;
 	}

 	return ds.getNumSets();
 }

