 	scanf("%d", &t);
 	for (int i = 1; i <= t; ++i) {
 		int n = run();
 		printf("Case #%d:", i);
 		for (int j = 0; j < n; ++j) {
 			printf(" %.10lf", ret[j]);
 		}
 		puts("");
 	}
 	return 0;
 }
