         printf("Case #%d: ",C++);
         scanf("%d",&n);
         memset(nadj,0,sizeof(nadj));
         memset(nadjinv,0,sizeof(nadjinv));
         for (int i=0;i<n;i++) {
             scanf("%d",amigo+i);
             amigo[i]--;
             adj[i][nadj[i]++] = amigo[i];
             adjinv[amigo[i]][nadjinv[amigo[i]]++] = i;
         }

         resp = 0;
         tarjan();

         // caso a <-> b
         int isso=0;
         for (int i=0;i<n;i++)
             if (amigo[ amigo[i] ] == i) {
                 int tt = dfsinv(i, amigo[i]) + dfsinv(amigo[i], i);
                 isso += tt;
             }
         isso /= 2;
         if (isso > resp)
             resp = isso;
         printf("%d\n",resp);
     }


     return 0;
 }

