 int obejscie(int v)
 {
   ob[v]=1;
   REP(jj,(v==0 ? 3 : 2))
   {
     if (!tab[v][jj].empty())
     {
       VI pom;
       REP(i,SIZE(tab[v][jj]))
       {
         int w=tab[v][jj][i];
         pom.PB(obejscie(w));
       }
       sort(ALL(pom)); reverse(ALL(pom));
       if (SIZE(pom)>1) wyn=max(wyn,2+pom[0]+pom[1]);
