 int gaub(vector<vector<ld>> a) {
     int n = a.size();
     ld det = 1;
     forn(i, n) {
         int v = i;
         for (int j = i; j < n; ++j) if (abs(a[j][i]) > abs(a[v][i])) v = j;
         swap(a[v], a[i]);
         if (!(abs(a[i][i]) > 1e-9)) return -1;
         det *= a[i][i];
         for (int j = i+1; j < n; ++j) {
             ld cf = a[j][i] / a[i][i];
             forn(k, n) a[j][k] -= a[i][k] * cf;
         }
     }
     assert(fabsl(round(det) - det) < 1e-5);
     return abs(round(det));
 }

