 int cnt[111][111];


 bool inside(int x, int y){
     return 0<=x && x<n && 0<=y && y<m;
 }
 void input(){
     scanf("%d%d",&n,&m);
 }

 void solve(){
     static int cas=1;
     printf("Case #%d: ",cas++);
     int res=0;
     for(int s=0; s<(1<<m); s++){
         memset(cnt,0,sizeof(cnt));
         bool fail=0;
         for(int i=0; i<m; i++){
             mat[0][i]= 2+bool((1<<i) & s);
         }
         for(int i=0; i<n-1&&!fail; i++){
             for(int j=0; j<m&&!fail; j++){
                 for(int d=0; d<n; d++){
                     int x=i+dx[d],y=(j+dy[d]+m)%m;
                     if(inside(x,y) && mat[x][y]==mat[i][j]){
                         cnt[i][j]++;
                     }
                 }
                 if(cnt[i][j]==mat[i][j]){
                     mat[i+1][j]=(mat[i][j]==2)?3:2;
                 }else if(cnt[i][j]==mat[i][j]-1){
                     mat[i+1][j]=(mat[i][j]==2)?2:3;
                 }else{
                     fail=1;
                 }
             }
         }
         for(int j=0; j<m&&!fail; j++){
             for(int d=0; d<n; d++){
                 int x=n-1+dx[d],y=(j+dy[d]+m)%m;
                 if(inside(x,y) && mat[x][y]==mat[n-1][j]){
                     cnt[n-1][j]++;
                 }
             }
             if(cnt[n-1][j]!=mat[n-1][j]){
                 fail=1;
             }
         }
         if(!fail)res++;
     }
