 #define FIND(m, w) ((m).find(w) != (m).end())

 const ull MOD = 1000000007;
 ull n, b;
 ull digits[90];
 ull size;
 ull memo[70][80][40][80];

 ull calc(ull depth, ull prev, ull up, ull bottom) {
   if (memo[depth][prev][up][bottom] != (ull)-1) { return memo[depth][prev][up][bottom]; }
   if (depth == size) {
     assert(prev == 0 && up == 0);
     if (bottom == 0) {
       return memo[depth][prev][up][bottom] = 1;
     } else {
       return memo[depth][prev][up][bottom] = 0;
     }
   }
   if (prev == b) {
     if (bottom == digits[depth]) {
       return calc(depth + 1, 0, 0, up);
     } else {
       return memo[depth][prev][up][bottom] = 0;
     }
   }
   ull ret = 0;
   ull nup = up + (bottom + prev) / b;
   ull nbottom = (bottom + prev) % b;
   ret += calc(depth, prev + 1, nup, nbottom);
   ret += calc(depth, prev + 1, up, bottom);
   //cout << depth << " " << prev << " " << up << " " << bottom << " " << ret << endl;
   return memo[depth][prev][up][bottom] = ret % MOD;
 }

 int main() {
   int test;
   scanf("%d", &test);
   int test_case = 0;
   while (test--) {
     MEMSET(memo, -1);
     test_case++;
     scanf("%lld %lld", &n, &b);
     ull m = n;
     for (size = 0; m > 0; size++, m /= b) {
       digits[size] = m % b;
     }
     int ans = calc(0, 0, 0, 0);
     printf("Case #%d: %d\n", test_case, ans);
   }
 }

