 bool report(int q)
 {
 	//cout << "test " << q << endl;
 	ans.insert(q);
 	if (ans.size() > 2) bun = true;
 	return bun;
 }

 void work(int m, int b[], int r)
 {
 	if (m <= 1)
 	{
 		//cout << "here" << endl;
 		bun = true;
 		return;
 	}

 	int i, r1;
 	int c[1000];
 	i = 2;
 	while (i < m && b[i] == b[0]) i+=2;
 	if (i >= m)
 	{
 		r1 = r;
 		if (i == m)
 		{
 			r1 = (r1+b[i%2])%mm;
 			if (report(r1)) return;
 		}
 		else
 		{
 			int k = 0;
 			for (int j = i%2; j < m; j+=2)
 				c[k++] = b[j];
 			work(k, c, r);
 			if (bun) return;
 		}
 	}

 	i = 3;
 	while (i < m && b[i] == b[1]) i+=2;
 	if (i >= m)
 	{
 		r1 = r;
 		if (i == m)
 		{
 			r1 = (r1+b[i%2])%mm;
 			if (report(r1)) return;
 		}
 		else
 		{
 			int k = 0;
 			for (int j = i%2; j < m; j+=2)
 				c[k++] = b[j];
 			work(k, c, r);
 			if (bun) return;
 		}
 	}
 }

