   void run(int testid) {
     cin >> N >> R;

     int result = 2;

     for (int x = 1; x < min((int)1.01e6, N); x++) {
       LD ty = (1E12 / (LD)(R * R) - x * x);
       if (ty < kEps) { break; }
       ty = sqrt(ty);

       debug(x, ty);

       int maxY = (int)floor(ty - kEps);
       for (int i = 0; i < 4; i++) {
         maxY++;
         double tt = (double)R * R * (double)(x * x + maxY * maxY);
         bool ok = false;
         if (tt < 1e13) {
           if (R * R * (x * x + maxY * maxY) < (int)1e12) {
             ok = true;
           }
         }

         if (!ok) { maxY--; }

       }

       mini(maxY, N - 1);
       if (maxY <= 0) { break; }

       debug(x, maxY);

       int numOk = 0;
       for (int d : divisors[x]) {
         debug(d, moebius[d]);
         numOk += moebius[d] * (maxY / d);
       }
       debug(x, numOk);
       result += numOk;
     }


     cout << "Case #" << testid << ": " << result << "\n";
   }
 };


