 {
 	int x,y;
 };
 bool operator<(const Point &a,const Point &b)
 {
 	return a.x<b.x || a.x==b.x && a.y<b.y;
 }

 Point B[10],P[10];
 int nB,nP,n,m;
 int x[6],y[6],father[6];
 char mapG[15][15];
 int A[15][15];
 map<string,int> M;
 vector<string> Q;
 int bx[6],by[6],mapH[15][15];
 string src,dest;
 bool flag;
 int current_step;

 int getfather(int v)
 {
 	return (father[v]<0)?v:(father[v]=getfather(father[v]));
 }
 void init()
 {
 	scanf("%d%d",&n,&m);
 	for (int i=0; i<n; i++)
 		scanf("%s",mapG[i]);
 }
 string getId(Point A[],int len)
 {
 	string R="";
 	for (int i=0;i<len;i++)
 	{
 		if (A[i].x<10) R=R+"0"+(char)(A[i].x+'0');
 		if (A[i].x==10) R=R+"10";
 		if (A[i].x==11) R=R+"11";
 		if (A[i].y<10) R=R+"0"+(char)(A[i].y+'0');
 		if (A[i].y==10) R=R+"10";
 		if (A[i].y==11) R=R+"11";
 	}
 	return R;
 }
 bool checkIt(int n)
 {
 	for (int i=0;i<n;i++) father[i]=-1;
 	for (int i=0;i<n;i++)
 		for (int j=i+1;j<n;j++)
 			if (abs(bx[i]-bx[j])+abs(by[i]-by[j])==1)
 			{
 				int u=getfather(i),v=getfather(j);
 				if (u!=v)
 					father[u]=v;
 			}
 	for (int i=0; i<n; i++)
 		if (getfather(i)!=getfather(0))
 			return false;
 	return true;
 }
 void push(int K)
 {
 	if (!flag && !checkIt(K))
 		return;
 	int x[6],y[6];
 	for (int i=0;i<K;i++) x[i]=bx[i],y[i]=by[i];
 	for (int i=0;i<K;i++)
 		for (int j=i+1;j<K;j++)
 			if (x[j]<x[i] || (x[j]==x[i] && y[j]<y[i]))
 			{
 				swap(x[i],x[j]);
 				swap(y[i],y[j]);
 			}
 	int step=current_step+1;
 	string state="";
 	for (int i=0;i<K;i++)
 	{
 		if (x[i]<10) state=state+"0"+(char)(x[i]+'0');
 		if (x[i]==10) state=state+"10";
 		if (x[i]==11) state=state+"11";
 		if (y[i]<10) state=state+"0"+(char)(y[i]+'0');
 		if (y[i]==10) state=state+"10";
 		if (y[i]==11) state=state+"11";
 	}
 	if (M.find(state)!=M.end()) return;
 	M.insert(make_pair(state, step));
 	Q.push_back(state);
 }
 void BFS(string state)
 {
 	memset(mapH,0,sizeof(mapH));
 	int K=LENGTH(state)/4;
 	for (int i=0;i<K;i++)
 	{
 		bx[i]=(state[i*4]-'0')*10+state[i*4+1]-'0';
 		by[i]=(state[i*4+2]-'0')*10+state[i*4+3]-'0';
 		mapH[bx[i]][by[i]]=1;
 	}
 	for (int i=0;i<K;i++)
 	{
 		bool isGoodX=false;
 		bool isGoodY=false;
 		if (bx[i]>0 && bx[i]<n-1 && A[bx[i]-1][by[i]]==0 
 									 && A[bx[i]+1][by[i]]==0
 									 && mapH[bx[i]-1][by[i]]==0
 									 && mapH[bx[i]+1][by[i]]==0)
 			isGoodX=true;
 		if (by[i]>0 && by[i]<m-1 && A[bx[i]][by[i]-1]==0
 									 && A[bx[i]][by[i]+1]==0
 									 && mapH[bx[i]][by[i]-1]==0
 									 && mapH[bx[i]][by[i]+1]==0)
 			isGoodY=true;
 		if (isGoodX)
 		{
 			bx[i]--;
 			push(K);
 			bx[i]++;
 			bx[i]++;
 			push(K);
 			bx[i]--;
 		}
 		if (isGoodY)
 		{
 			by[i]--;
 			push(K);
 			by[i]++;
 			by[i]++;
 			push(K);
 			by[i]--;
 		}
 	}
 }
 bool checkIt(string state)
 {
 	int n=LENGTH(state)/4;
 	for (int i=0;i<n;i++)
 	{
 		x[i]=(state[i*4]-'0')*10+state[i*4+1]-'0';
 		y[i]=(state[i*4+2]-'0')*10+state[i*4+3]-'0';
 		father[i]=-1;
 	}
 	for (int i=0; i<n; i++)
 		for (int j=i+1; j<n; j++)
 			if (abs(x[i]-x[j])+abs(y[i]-y[j])==1)
 			{
 				int x=getfather(i);
 				int y=getfather(j);
 				if (x!=y)
 					father[x]=y;
 			}
 	for (int i=0; i<n; i++)
 		if (getfather(i)!=getfather(0))
 			return false;
 	return true;
 }
 int solve()
 {
 	for (int i=0;i<n;i++)
 		for (int j=0;j<m;j++)
 		{
 			if (mapG[i][j]=='.') A[i][j]=0;
 			if (mapG[i][j]=='#') A[i][j]=-1;
 			if (mapG[i][j]=='x') A[i][j]=2;
 			if (mapG[i][j]=='o') A[i][j]=1;
 			if (mapG[i][j]=='w') A[i][j]=3;
 		}
 	M.clear();
 	Q.clear();
 	nB=nP=0;
 	for (int i=0;i<n;i++)
 		for (int j=0;j<m;j++)
 			if (A[i][j]>0)
 			{
 				if ((A[i][j]&1)==1) B[nB].x=i,B[nB++].y=j;
 				if ((A[i][j]&2)==2) P[nP].x=i,P[nP++].y=j;
 				if (A[i][j]>0) A[i][j]=0;
 			}
 	src=dest="";
 	sort(B,B+nB);
 	sort(P,P+nP);
 	if (nB!=nP) return -1;
 	src=getId(B,nB);
 	dest=getId(P,nP);
 	Q.push_back(src);
 	M.insert(make_pair(src, 0));
 	for (int cl=0;cl<SIZE(Q);cl++)
 	{
 		src=Q[cl];
 		if (src==dest) return M[src];
 		current_step=M[src];
 		flag=false;
 		if (checkIt(src)) flag=true;
 		BFS(src);
 	}
 	return -1;
 }
