 using namespace std;

 vector<int> loc;
 vector<int> speed;

 int simulate(int bar, int k, int t) {
 	int arrived=0;
 	int ct = 0;
 	int swapt = 0;
 	while(ct < t) {
 		for(int i=loc.size()-1; i>=0; --i) {
 			if(loc[i] < bar) {
 				loc[i] += speed[i];
 				if(i < loc.size()-1) {
 					if(loc[i+1] < bar) {
 						if(loc[i] >= loc[i+1]) {
 							++swapt;
 							swap(speed[i], speed[i+1]);
 							loc[i] = loc[i+1]-1;
 						}
 					}
 				}

 				if(loc[i] >= bar) arrived+=1;
 			}
 		}
 	//	cout<<endl;

 		++ct;
 	}
 	if(arrived < k) return -1;
 	return swapt;
 }

