 void swap(int i, int j)
 {
 	char t = buf[i];
 	buf[i] = buf[j];
 	buf[j] = t;
 }

 int asdf(const void *a, const void *b)
 {
 	return (*(char*)b - *(char*)a);
 }

 void aa()
 {
 	int len = strlen(buf);
 	for (int j=1; j<len; ++j) {
 		for (int i=0; i<j; ++i) {
 			if (buf[j] < buf[i]) {
 				swap(i, j);
 				qsort(buf, j, sizeof(char), asdf);
 				return;
 			}
 		}
 	}
 	buf[len] = '0';
 	buf[len+1] = '\0';
 	char c;
 	int pos = -1;
 	for (int i=0; i<len; ++i) {
 		if (buf[i] != '0') {
 			if (pos == -1) {
 				c = buf[i];
 				pos = i;
 			}
 			if (c > buf[i]) {
 				c = buf[i];
 				pos = i;
 			}
 		}
 	}
 	swap(len, pos);
 	qsort(buf, len, sizeof(char), asdf);
 }

