 const int MAX_H = 512;
 const int MAX_W = 512;

 int W, H, B;
 int inc[MAX_H][MAX_W], out[MAX_H][MAX_W];
 bool valid[MAX_H][MAX_W];
 bool vis[MAX_W][MAX_W];

 bool dfs(int x, int y) {
   if (x >= H) {
     return true;
   }
   if (!valid[x][y] || vis[x][y]) {
     return false;
   }
   vis[x][y] = true;
   if (y - 1 >= 0 && (x == 0 || (x - 1 >= 0 && !valid[x - 1][y - 1])) && dfs(x, y - 1)) {
     valid[x][y] = false;
     return true;
   }
   if (dfs(x + 1, y)) {
     valid[x][y] = false;
     return true;
   }
   vis[x][y] = false;
   return false;
 }

 int work() {
   scanf("%d%d%d", &W, &H, &B);
   fill(valid[0], valid[MAX_H], true);
   fill(vis[0], vis[MAX_H], false);
   REP (i, B) {
     int x0, y0, x1, y1;
     scanf("%d%d%d%d", &y0, &x0, &y1, &x1);
     if (x0 > x1) swap(x0, x1);
     if (y0 > y1) swap(y0, y1);
     for (int x = x0; x <= x1; ++x) {
       for (int y = y0; y <= y1; ++y) {
         valid[x][y] = false;
       }
     }
   }
   int ans = 0;
   REP (y, W) {
     if (dfs(0, y)) {
       ++ans;
     }
   }
   return ans;
 }

