 void update() {
 	REP(i, 37) c[i] = a[i] + invest[i];
 	int numSame = 0;
 	REP(i, 37) if (c[i] == c[0]) ++numSame;
 	REP(i, 36) assert(c[i] <= c[i + 1]);
 	double ans = 0;
 	REP(i, 37) if (c[i] == c[0]) {
 		ans += invest[i] / (double) numSame * 36 - invest[i];
 	} else ans -= invest[i];

 	e = max(e, ans);
 }

