 void solve() {
 	cin >> b >> n;
 	CLEAR(a);
 	REP(i, n) cin >> a[i];
 	sort(a, a + 37);
 	CLEAR(invest);
 	e = 0.0;
 	ll b0 = b;
 	for (int i = 0; i < 36; ) {
 		int j = i;
 		while (j < 36 && a[i] == a[j]) {
 			++j;
 		}
 		ll most = a[j] - a[i];
 		ll can = min(b / j, most - 1);
 		if (most == 0) break;
 		for (int k = 0; k < j; ++k) invest[k] += can;
 		update();
 		b -= can * j;
 		if (b >= j) {
 			for (int k = 0; k < j; ++k) ++invest[k];
 			b -= j;
 			update();
 		} else break;
 		i = j;
 	}
 	b = b0;
 	CLEAR(invest);
 	for (int i = 0; i < 36; ) {
 		int j = i;
 		while (j < 36 && a[i] == a[j]) {
 			++j;
