 		ll can = min(b / j, most - 1);
 		if (most == 0) break;
 		for (int k = 0; k < j; ++k) invest[k] += can;
 		if (invest[0]) {
 			CLEAR(change);
 			for (int k = 0; k < j && invest[k]; ++k) {
 				change[k] = true;
 				--invest[k];
 				update();
 			}
 			for (int k = 0; k < j && change[k]; ++k) {
 				++invest[k];
 			}
 		}
 		b -= can * j;
 		b -= j;
 		for (int k = 0; k < j; ++k) ++invest[k];
 		for (int k = 0; k < j; ++k) {
 			--invest[k];
