 		}
 		if (b >= j) {
 			for (int k = 0; k < j; ++k) ++invest[k];
 			b -= j;
 		} else {
 			break;
 		}
 		i = j;
 	}

 	printf("Case #%d: %.10f\n", ++nowCase, e);
 }

