 			base = N+M;
 		for (int i=0; i<base; i++)
 			if (c[i].flag && c[i].t > 0)
 			{
 				base+=c[i].c;
 				turn+=c[i].t;
 				if (c[i].c==0) c0--;
 				else if (c[i].c==1) c1--;
 				else if (c[i].c==2) c2--;
 				flag = false;
 				c[i].flag = false;
 				break;
 			}
 		if (c2 > 0 && flag)
 		{
 			for (int i=0; i<base; i++)
 			if (c[i].flag && c[i].c == 2)
 			{
 				base+=c[i].c;
 				turn+=c[i].t;
 				c2--;
 				flag = false;
 				c[i].flag = false;
 				break;
 			}
 		}
 		if (c1 > 0 && flag)
 		{
 			for (int i=0; i<base; i++)
 			if (c[i].flag && c[i].c == 1)
 			{
 				base+=c[i].c;
 				turn+=c[i].t;
 				c1--;
 				flag = false;
 				c[i].flag = false;
 				break;
 			}
 		}
 		if (c0 > 0 && flag)
 		{
 			for (int i=0; i<base; i++)
 			if (c[i].flag && c[i].c == 0)
 			{
 				base+=c[i].c;
 				turn+=c[i].t;
 				c0--;
 				flag = false;
 				c[i].flag = false;
 				break;
 			}
 		}
 		if (c0 <=0 && c1<=0 && c2<=0)
 			return true;
 		turn--;
 	}
 	return false;
 }

