 int go(int mask,int cr,int cc){
     int& ret = dp[mask][cr][cc];
     if(ret>=0) return ret;
     ret=0;
     for(int i=-1;i<2;++i) for(int j=-1;j<2;++j){
         int tr = cr+i;
         int tc = cc+j;
         if(tr<0||tr>=r) continue;
