 inline bool cmp(const Point& a, const Point& b)
 {
     if (a.y != b.y) return a.y < b.y;
     return a.x < b.x;
 }

 inline int lowbit(int n)
 {
     return n & -n;
 }

 bool dfs(int k)
 {
     if (k == n) return true;
     if (c == 100000000)
         return false;
     c++;
     if (p[k].y > p[k - 1].y + 1)
     {
         color[k] = 0;
         return dfs(k + 1);
     }
     ch[k] = (1 << res) - 1;
     if (p[k].y == p[k - 1].y)
         ch[k] &= ~(1 << color[k - 1]);
     if (dl[k] != -1)
         ch[k] &= ~(1 << color[dl[k]]);
     if (dr[k] != -1)
         ch[k] &= ~(1 << color[dr[k]]);
 //    printf("res = %d, ch[%d] = %d\n", res, k, ch[k]);
     for (int i = 0; i < res; i++)
         if (ch[k] & (1 << i))
         {
             color[k] = i;
             if (dfs(k + 1))
                 return true;
         }
     return false;
 }

