 const long double eps = 1e-9;

 int main() {
   int number_of_tests;
   std::cin >> number_of_tests;
   for (int test_number = 0; test_number < number_of_tests; ++test_number) {
     int n, k;
     std::cin >> n >> k;
     long double u;
     std::cin >> u;
     std::vector<long double> probs(n);
     long double total_sum = 0;
     long double total_product = 1;
     for (int i = 0; i < n; ++i) {
       std::cin >> probs[i];
       total_sum += probs[i];
       total_product *= probs[i];
     }
     std::sort(probs.rbegin(), probs.rend());
     long double sum = 0;
     long double best = total_product;
     for (int i = 0; i <= n; ++i) {
       if (i > 0) {
         sum += probs[i - 1];
       }
       long double to_add = i - sum;
       if (to_add > u + eps) {
         //std::cerr << ":wewqe" << ' ' << to_add << ' ' << u << std::endl;
         continue;
       }
       long double left = u - to_add;
       if (i < n) {
         long double left_each = left / (long double)(n - i);
         if (probs[i] > left_each + eps) {
           continue;
         }
         long double result = 1;
         for (int j = 0; j < n - i; ++j) {
           result *= left_each;
         }
         best = std::max(best, result);
       } else {
         best = 1;
       }
     }
     std::cout << "Case #" << test_number + 1 << ": ";
     std::cout << std::fixed << std::setprecision(20) << best << std::endl;
   }
   return 0;
 }

