 const int MOD = 1000002013;

 inline int points(int d) {
     return (LL) d * (d - 1) / 2 % MOD;
 }

 int solve() {
     int n, m;
     cin >> n >> m;
     LL expected = 0;
     map<int, LL> D;
     REP(i, m) {
         int x, y, p;
         cin >> x >> y >> p;
         expected += (LL) p * points(y - x);
         expected %= MOD;
         D[x] += p;
         D[y] -= p;
     }

     LL real = 0;
     priority_queue<pair<int, LL> > Q;
     FORE(i, D) {
         if (i->second > 0) {
             Q.push(*i);
         } else if (i->second < 0) {
             LL c = - i->second;
             while (c > 0) {
                 pair<int, LL> t = Q.top();
                 Q.pop();
                 if (t.second <= c) {
                     real += t.second % MOD * points(i->first - t.first);
                     real %= MOD;
                     c -= t.second;
                 } else {
                     real += c % MOD * points(i->first - t.first);
                     real %= MOD;
                     t.second -= c;
                     Q.push(t);
                     c = 0;
                 }
             }
         }
     }

     return (real - expected + MOD) % MOD;
 }

 int main() {
     int t;
     cin >> t;
     FOR(i, 1, t) {
         cout << "Case #" << i << ": " << solve() << endl;
     }
 }

