         REP(m, M) {
             int o, e, p;
             scanf("%d %d %d ", &o, &e, &p);
             if (oindex.count(o) == 0) {
                 oindex[o] = oocnt;
                 oo[oocnt++] = o;
             }
             if (eindex.count(e) == 0) {
                 eindex[e] = eecnt;
                 ee[eecnt++] = e;
             }
             pp[oindex[o]][eindex[e]] += p;
         }

         long long sum = 0;
         bool done = false;

         while (!done) {
             done = true;

             for (int idxo1 = 0;idxo1 < oocnt;idxo1++) {
                 for (int idxe1 = 0;idxe1 < eecnt;idxe1++) {
                     for (int idxo2 = 0;idxo2 < oocnt;idxo2++) {
