                                 pp[idxo1][idxe1] -= pdiff;
                                 pp[idxo2][idxe2] -= pdiff;
                                 pp[idxo1][idxe2] += pdiff;
                                 pp[idxo2][idxe1] += pdiff;
                             }
                         }
                     }
                 }
             }
         }

