                                     {
                                         next[i][j][sum1] = next1;
                                     }
                                 }
                                 // straight move
                                 int ii1 = i + dx1[k] * 2;
                                 int jj1 = j + dy1[k] * 2;
                                 if (ii >= 0 && ii < W && jj >= 0 && jj < W
                                     && ii1 >= 0 && ii1 < W && jj1 >= 0 && jj1 < W)
