                                     {
                                         next[ii1][jj1][sum1] = next1;
                                     }
                                 }
                             }
                         }
                     }
                 }
             }

             curr = next;
         }
         for (int i = 0 ; i < Q ; ++i)
             std::cout << queries[q[i] + MAX] << "\n";
     }
     return 0;
 }

