 int main(){
     cin>>t;
     for (int l=0;l<t;l++){
         unsigned long long n,a,b,c,d,x0,y0,m;
         cin>>n>>a>>b>>c>>d>>x0>>y0>>m;
         unsigned long long x[n],y[n];
         x[0]=x0;y[0]=y0;
         for (int i=1;i<n;i++){
             x[i]=(a*x[i-1]+b)%m;
             y[i]=(c*y[i-1]+d)%m;
         }
         unsigned long long ans = 0;
         for (int i=0;i<n-2;i++){
             for (int j=i+1;j<n-1;j++){
                 if (x[i]==x[j]&&y[i]==y[j]) continue;
                 for (int k=j+1;k<n;k++){
                     if (x[i]==x[k]&&y[i]==y[k]) continue;
                     if (x[j]==x[k]&&y[j]==y[k]) continue;
                     if ((x[i]+x[j]+x[k])%3==0&&(y[i]+y[j]+y[k])%3==0)
                         ans++;
                 }
             }
         }
         cout<<"Case #"<<(l+1)<<": "<<ans<<endl;
     }
     return 0;
 }

#include<cstdio>
 #include<cstring>
 #include<iostream>
 #include<string>
 #include<algorithm>
 using namespace std;

 long long n,M,t,A,B,C,D,x0,y0,ans;
 long long pnt[110][2];

 int main()
 {
 	freopen("in.txt","r",stdin);freopen("out.txt","w",stdout);
 	scanf("%lld",&t);
 	for(int cs=1;cs<=t;cs++)
 	{
 		scanf("%lld%lld%lld%lld%lld%lld%lld%lld",&n,&A,&B,&C,&D,&x0,&y0,&M);
 		memset(pnt,0,sizeof(pnt));
 		ans=0;
 		pnt[0][0]=x0,pnt[0][1]=y0;
 		for(int i=1;i<n;i++)
 		{
 			x0 = (A * x0 + B) % M;
 			y0 = (C * y0 + D) % M;
 			pnt[i][0]=x0;
 			pnt[i][1]=y0;
 		}
 		for(int i=0;i<n;i++)
 		{
 			for(int j=i+1;j<n;j++)
 			{
 				for(int k=j+1;k<n;k++)
 				{
 					long long sumx=0,sumy=0;
 					sumx=pnt[i][0]+pnt[j][0]+pnt[k][0];
 					sumy=pnt[i][1]+pnt[j][1]+pnt[k][1];
 					if(sumx%3==0 && sumy%3==0)ans++;
 				}
 			}
 		}
 		printf("Case #%d: %lld\n",cs,ans);
 	}
 	return 0;
 }
